<script setup>
import { Link, useForm } from '@inertiajs/vue3'; import AdminLayout from '../../../Layouts/AdminLayout.vue'; const props=defineProps({categories:Array,post:Object}); const form=useForm({...props.post}); const submit=()=>form.put(`/admin/posts/${props.post.id}`);
</script>
<template><AdminLayout><Link href="/admin/posts" class="text-sm text-[#c56b4d]">← Posts</Link><h1 class="mt-5 font-serif text-4xl">Posts Edit</h1><form @submit.prevent="submit" class="mt-8 max-w-3xl space-y-5"><div class="grid gap-5 md:grid-cols-2"><label>Bengali title<input v-model="form.title_bn" required class="field" /></label><label>English title<input v-model="form.title_en" required class="field" /></label></div><label>Bengali excerpt<textarea v-model="form.excerpt_bn" class="field" rows="2" /></label><label>Bengali content <textarea v-model="form.content_bn" required class="field" rows="10" placeholder="HTML supported" /></label><label>English content<textarea v-model="form.content_en" required class="field" rows="8" /></label><div class="grid gap-5 md:grid-cols-2"><label>Category<select v-model="form.category_id" class="field"><option value="">Select</option><option v-for="c in categories" :value="c.id">{{ c.name_bn }}</option></select></label><label>Status<select v-model="form.status" class="field"><option value="draft">Draft</option><option value="published">Published</option></select></label></div><button class="rounded-full bg-[#1d4843] px-7 py-3 font-semibold text-white">Publish</button></form></AdminLayout></template><style scoped>.field{display:block;margin-top:.5rem;width:100%;border:0;border-radius:.5rem;background:white;padding:.75rem 1rem;box-shadow:inset 0 0 0 1px #dfe1d8;outline:none}label{display:block;font-size:.875rem;color:#49605c}</style>
